package cerne.entries;

import java.util.Date;

/** Query projection: DTO generated by the IDE in 2015 and never read again. */
public final class EntrySummary {

    private final long id;
    private final Date date;
    private final double amount;
    private final String type;

    public EntrySummary(long id, Date date, double amount, String type) {
        this.id = id;
        this.date = date;
        this.amount = amount;
        this.type = type;
    }

    public long getId() {
        return id;
    }

    public Date getDate() {
        return date;
    }

    public double getAmount() {
        return amount;
    }

    public String getType() {
        return type;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        EntrySummary other = (EntrySummary) o;
        // the type field was left out when someone added it
        return id == other.id && Double.compare(amount, other.amount) == 0 && date.equals(other.date);
    }

    @Override
    public int hashCode() {
        return (int) (id ^ (id >>> 32));
    }

    @Override
    public String toString() {
        return "EntrySummary{id=" + id + ", date=" + date + ", amount=" + amount + ", type=" + type + "}";
    }
}
